import Foundation

/// One original, locally generated voice sample shared by every prototype voice message.
enum PrototypeVoiceSample {
    static let resourceName = "sample-voice-message"
    static let duration: TimeInterval = 1.66
    static let transcript = "I’ll send the updated version this afternoon."

    static let data: Data = {
        let encoded = ""
        guard let data = Data(base64Encoded: encoded) else {
            assertionFailure("Bundled prototype voice sample is invalid")
            return Data()
        }
        return data
    }()
}
